package com.yuri.music;
import android.app.*;import android.content.*;import android.media.MediaMetadata;import android.media.session.*;import android.os.*;import org.json.JSONObject;
public class PlaybackService extends Service{
 static PlaybackService instance;MediaSession session;PowerManager.WakeLock lock;boolean playing;String title="Nocturne",artist="";
 static void update(Context context,JSONObject body){if(!body.optBoolean("playing")&&instance==null)return;Intent intent=new Intent(context,PlaybackService.class).putExtra("title",body.optString("title")).putExtra("artist",body.optString("artist")).putExtra("playing",body.optBoolean("playing")).putExtra("duration",body.optLong("duration",0)).putExtra("position",body.optLong("position",0));if(instance==null)context.startForegroundService(intent);else context.startService(intent);}
 @Override public void onCreate(){super.onCreate();instance=this;NotificationManager manager=getSystemService(NotificationManager.class);manager.createNotificationChannel(new NotificationChannel("music","Reprodução de música",NotificationManager.IMPORTANCE_LOW));session=new MediaSession(this,"Nocturne");session.setCallback(new MediaSession.Callback(){@Override public void onPlay(){MainActivity.command("resume");}@Override public void onPause(){MainActivity.command("pause");}@Override public void onSkipToNext(){MainActivity.command("next");}@Override public void onSkipToPrevious(){MainActivity.command("previous");}@Override public void onSeekTo(long position){MainActivity.seek(position);}});session.setActive(true);lock=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"YuriMusic:Playback");}
 PendingIntent command(String action,int request){return PendingIntent.getService(this,request,new Intent(this,PlaybackService.class).setAction(action),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 @Override public int onStartCommand(Intent intent,int flags,int start){if(intent==null)return START_NOT_STICKY;String action=intent.getAction();if(action!=null){MainActivity.command(action);return START_NOT_STICKY;}playing=intent.getBooleanExtra("playing",false);title=intent.getStringExtra("title");artist=intent.getStringExtra("artist");if(playing&&!lock.isHeld())lock.acquire();if(!playing&&lock.isHeld())lock.release();session.setMetadata(new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,title).putString(MediaMetadata.METADATA_KEY_ARTIST,artist).putLong(MediaMetadata.METADATA_KEY_DURATION,intent.getLongExtra("duration",0)).build());session.setPlaybackState(new PlaybackState.Builder().setActions(PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_SKIP_TO_NEXT|PlaybackState.ACTION_SKIP_TO_PREVIOUS|PlaybackState.ACTION_SEEK_TO).setState(playing?PlaybackState.STATE_PLAYING:PlaybackState.STATE_PAUSED,intent.getLongExtra("position",0),playing?1:0).build());PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification notification=new Notification.Builder(this,"music").setSmallIcon(android.R.drawable.ic_media_play).setLargeIcon(android.graphics.BitmapFactory.decodeResource(getResources(),R.drawable.nocturne_mascot)).setContentTitle(title).setContentText(artist).setContentIntent(open).setOnlyAlertOnce(true).setOngoing(playing).setVisibility(Notification.VISIBILITY_PUBLIC).setStyle(new Notification.MediaStyle().setMediaSession(session.getSessionToken()).setShowActionsInCompactView(0,1,2)).addAction(new Notification.Action.Builder(android.R.drawable.ic_media_previous,"Anterior",command("previous",1)).build()).addAction(new Notification.Action.Builder(playing?android.R.drawable.ic_media_pause:android.R.drawable.ic_media_play,playing?"Pausar":"Reproduzir",command(playing?"pause":"resume",2)).build()).addAction(new Notification.Action.Builder(android.R.drawable.ic_media_next,"Próxima",command("next",3)).build()).build();if(playing)startForeground(1,notification);else{getSystemService(NotificationManager.class).notify(1,notification);stopForeground(false);}return START_NOT_STICKY;}
 @Override public void onDestroy(){instance=null;if(lock!=null&&lock.isHeld())lock.release();if(session!=null)session.release();super.onDestroy();}@Override public IBinder onBind(Intent intent){return null;}
}
